package com.aistock.prediction.question;
import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.*;
public final class QuestionSamples {
 public static final ObjectMapper M=new ObjectMapper();
 public static ObjectNode analysis(boolean prediction){var n=M.createObjectNode().put("analysisId","11111111-1111-4111-8111-111111111111").put("createdAt","2026-10-07T14:03:36Z").put("contextHash","a".repeat(64));var c=n.putObject("context").put("instrumentId","SH600030").put("marketVersionId","22222222-2222-4222-8222-222222222222").put("provider","baostock").put("priceBasis","RAW").put("formulaVersion","tech-v1").put("from","2026-07-07").put("to","2026-10-07");var f=c.putObject("facts").put("STOCK","SH600030").put("AS_OF","2026-09-30").put("CLOSE","25.86元").put("MA5_STATE","收盘价低于均线").put("MACD_STATE","DIF低于DEA").put("RSI_STATE","RSI处于中间观察区").put("BASIS_LIMIT","未复权价格限制").put("FRESHNESS_LIMIT","已保存历史并非实时行情");if(prediction){c.putObject("prediction").put("predictionId","33333333-3333-4333-8333-333333333333").put("originDate","2026-09-30").putNull("verificationVersionId");f.put("PRED_ORIGIN_DATE","2026-09-30").put("PRED_TREND","预测序列上行").put("PRED_RELATIVE_ORIGIN","部分低于原点").put("PRED_VERIFICATION","尚无有效样本，不能评价准确性").put("PRED_LIMIT","预测仅参考").put("PRED_CONTEXT_RELATION","历史与预测口径不同");for(int i=1;i<=5;i++){f.put("PRED_D"+i,"2026-10-"+(10+i));f.put("PRED_P"+i,"25.8元");}}return n;}
 public static JsonNode raw(String topic,String readout,String...refs){var n=M.createObjectNode().put("status","ANSWERED").put("topic",topic);var a=n.putArray("paragraphs");part(a,"overview","截至{{AS_OF}}。","AS_OF");part(a,"readout",readout,refs);part(a,"risk","{{BASIS_LIMIT}}。{{FRESHNESS_LIMIT}}。","BASIS_LIMIT","FRESHNESS_LIMIT");return n;}
 static void part(ArrayNode a,String kind,String text,String...refs){var p=a.addObject().put("kind",kind).put("template",text);p.set("refs",M.valueToTree(refs));}
}
